// A card's sentence translated by the learner's AI: the Vocab card's "Generate" beside "+ Sentence translation"
// (components/wordeditor.js). The owner, 2026-11-27: "when I pull a word and it gives me the surrounding context into
// my new card, there's no current way for me to get the sentence translation … just have it say generate … And that
// should then be able to be generated by AI." A word saved from a podcast or a video keeps the sentence it was heard
// in, with no translation; this fills one in, in the learner's own language, and the learner can still change it.
// The prompt and the reading of the answer need no screen, so they are tested on their own
// (tests/js/sentencetranslate.test.mjs). Shared by every version (the phone's define-service.js has the same askAi).

import { stripMarks } from "../cardtext.js";

/** The answer asked for: the translation and nothing else. */
export const TRANSLATE_SCHEMA = {
  type: "object",
  properties: {
    translation: { type: "string", description: "The whole sentence translated." },
  },
  required: ["translation"],
  additionalProperties: false,
};

/** The sentence of card `v` as it is translated: its text without the card's marks, on one line. */
export const sentenceOf = (v) => stripMarks(String((v && v.sentence) || "")).replace(/\s+/g, " ").trim();

/**
 * What the AI is asked ({system, user, schema}, as definer.js askJson takes it): `sentence` in `study` (the language
 * being learned, by its English name) translated into `speaks` (the learner's own). `word`: the card's word, so the
 * translation keeps its meaning in this sentence (`meaning`, the card's, when it has one).
 */
export function translatePrompt(sentence, { study = "the language being learned", speaks = "English", word = "", meaning = "" } = {}) {
  const system = `You translate the example sentences on a language learner's flashcards from ${study} into ${speaks}.
Translate the whole sentence faithfully and naturally, the way a native ${speaks} speaker would say the same thing, keeping its meaning, tone and register (everyday speech stays everyday, slang stays slang).
The sentence may be cut from speech, a podcast or a video, so it can start or stop in the middle of a thought: translate exactly what is there as it is, and never add, finish or explain anything.
Write only ${speaks}, with no notes, quotation marks or alternatives. Return only the JSON object.`;
  const lines = [`Sentence (${study}): ${sentence}`];
  if (word) lines.push(`The word being learned in it: ${word}${meaning ? ` (meaning here: ${meaning})` : ""}`);
  return { system, user: lines.join("\n"), schema: TRANSLATE_SCHEMA };
}

/** The translation in the AI's answer, tidied (one line, no quotation marks around it), or "" when there is none. */
export function readTranslation(answer) {
  const raw = answer && typeof answer.translation === "string" ? answer.translation : "";
  return raw.replace(/\s+/g, " ").trim().replace(/^["“”«»'‘’]+|["“”«»'‘’]+$/g, "").trim();
}

/**
 * Card `v`'s sentence translated: resolves to the translation (a string), or throws.
 * `ask(prompt)` is define-service.js askAi (it throws "NO_KEY" with no key, and a plain message with AI switched
 * off: the caller shows components/fixit.js offerFix for both); `study`/`speaks` as for translatePrompt.
 */
export async function translateCardSentence(v, { ask, study, speaks }) {
  const sentence = sentenceOf(v);
  if (!sentence) throw new Error("This card has no sentence to translate.");
  const answer = await ask(translatePrompt(sentence, {
    study, speaks, word: String((v && v.text) || "").trim(), meaning: stripMarks(String((v && v.meaning) || "")).trim(),
  }));
  const out = readTranslation(answer);
  if (!out) throw new Error("The AI didn't write a translation. Try again.");
  return out;
}
